-- SubjectDict seed data (sinh tự động từ data/seed.json — đừng sửa tay)
-- 4 môn, 12 chủ đề, 100 thuật ngữ

begin;

on conflict (id) do update set name_vi = excluded.name_vi, name_en = excluded.name_en, color = excluded.color, sort = excluded.sort;

on conflict (id) do update set subject_id = excluded.subject_id, name_vi = excluded.name_vi, name_en = excluded.name_en, sort = excluded.sort;

on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, grade = excluded.grade, term_en = excluded.term_en, term_vi = excluded.term_vi, ipa = excluded.ipa, pos = excluded.pos, def_en = excluded.def_en, def_vi = excluded.def_vi, example_en = excluded.example_en, example_vi = excluded.example_vi, note = excluded.note, related = excluded.related, status = excluded.status;

commit;
