insert into public.terms (id, subject_id, topic_id, grade, term_en, term_vi, ipa, pos, def_en, def_vi, example_en, example_vi, note, related, status) values
  ('integer', 'math', 'm-num', 6, 'integer', 'số nguyên', '/ˈɪntɪdʒə(r)/', 'noun', 'A whole number that can be positive, negative or zero.', 'Số không có phần thập phân, có thể dương, âm hoặc bằng 0.', '−5, 0 and 12 are all integers.', '−5, 0 và 12 đều là số nguyên.', '', array['decimal','fraction']::text[], 'published'),
  ('fraction', 'math', 'm-num', 6, 'fraction', 'phân số', '/ˈfrækʃn/', 'noun', 'A number that shows a part of a whole, written as a/b.', 'Số biểu thị một phần của một tổng thể, viết dưới dạng a/b.', 'Three quarters, or 3/4, is a fraction.', 'Ba phần tư, tức 3/4, là một phân số.', '', array['numerator','denominator','decimal']::text[], 'published'),
  ('numerator', 'math', 'm-num', 6, 'numerator', 'tử số', '/ˈnjuːməreɪtə(r)/', 'noun', 'The number above the line in a fraction.', 'Số nằm phía trên gạch ngang của phân số.', 'In the fraction 2/5, the numerator is 2.', 'Trong phân số 2/5, tử số là 2.', '', array['denominator','fraction']::text[], 'published'),
  ('denominator', 'math', 'm-num', 6, 'denominator', 'mẫu số', '/dɪˈnɒmɪneɪtə(r)/', 'noun', 'The number below the line in a fraction. It cannot be zero.', 'Số nằm phía dưới gạch ngang của phân số, phải khác 0.', 'To add 1/4 and 1/3, we first find a common denominator.', 'Để cộng 1/4 và 1/3, trước hết ta tìm mẫu số chung.', '', array['numerator','fraction']::text[], 'published'),
  ('prime-number', 'math', 'm-num', 6, 'prime number', 'số nguyên tố', '/ˌpraɪm ˈnʌmbə(r)/', 'noun', 'A natural number greater than 1 that has only two factors: 1 and itself.', 'Số tự nhiên lớn hơn 1, chỉ có hai ước là 1 và chính nó.', '2, 3, 5 and 7 are prime numbers.', '2, 3, 5 và 7 là các số nguyên tố.', '', array['factor','multiple']::text[], 'published'),
  ('factor', 'math', 'm-num', 6, 'factor', 'ước (thừa số)', '/ˈfæktə(r)/', 'noun', 'A number that divides another number exactly, with no remainder.', 'Số chia hết một số khác mà không có số dư.', 'The factors of 12 are 1, 2, 3, 4, 6 and 12.', 'Các ước của 12 là 1, 2, 3, 4, 6 và 12.', 'Trong tiếng Việt thường gọi là "ước". "Factor" cũng có nghĩa là "thừa số" trong phép nhân, và "yếu tố" trong văn nói hằng ngày.', array['multiple','prime-number']::text[], 'published'),
  ('multiple', 'math', 'm-num', 6, 'multiple', 'bội', '/ˈmʌltɪpl/', 'noun', 'The result of multiplying a number by a whole number.', 'Kết quả khi nhân một số với một số tự nhiên.', '15 and 20 are multiples of 5.', '15 và 20 là bội của 5.', 'Dễ nhầm với "factor": 3 là ước (factor) của 12, còn 12 là bội (multiple) của 3.', array['factor']::text[], 'published'),
  ('decimal', 'math', 'm-num', 6, 'decimal', 'số thập phân', '/ˈdesɪml/', 'noun', 'A number with a decimal point, such as 2.5.', 'Số có phần thập phân, ví dụ 2,5.', 'Write 1/2 as a decimal: 0.5.', 'Viết 1/2 dưới dạng số thập phân: 0,5.', 'Tiếng Anh dùng dấu chấm (2.5), tiếng Việt dùng dấu phẩy (2,5). Đọc "2.5" là "two point five".', array['fraction','percentage']::text[], 'published'),
  ('percentage', 'math', 'm-num', 6, 'percentage', 'tỉ số phần trăm', '/pəˈsentɪdʒ/', 'noun', 'An amount shown as a part of 100, using the sign %.', 'Lượng được biểu thị dưới dạng phần của 100, dùng kí hiệu %.', 'Forty percent of the students walk to school.', 'Bốn mươi phần trăm học sinh đi bộ đến trường.', '"percent" đi với con số (40 percent), còn "percentage" dùng khi không có số (a high percentage).', array['decimal','ratio']::text[], 'published'),
  ('ratio', 'math', 'm-num', 7, 'ratio', 'tỉ số', '/ˈreɪʃiəʊ/', 'noun', 'A comparison of two amounts, written as a : b.', 'Phép so sánh hai đại lượng, viết dưới dạng a : b.', 'The ratio of boys to girls in our class is 3 : 4.', 'Tỉ số giữa số bạn nam và số bạn nữ trong lớp là 3 : 4.', '', array['proportion','percentage']::text[], 'published'),
  ('proportion', 'math', 'm-num', 7, 'proportion', 'tỉ lệ thức', '/prəˈpɔːʃn/', 'noun', 'An equation that shows two ratios are equal.', 'Đẳng thức của hai tỉ số.', '2 : 3 = 4 : 6 is a proportion.', '2 : 3 = 4 : 6 là một tỉ lệ thức.', '"directly proportional" = tỉ lệ thuận; "inversely proportional" = tỉ lệ nghịch.', array['ratio']::text[], 'published'),
  ('square-root', 'math', 'm-num', 7, 'square root', 'căn bậc hai', '/ˌskweə ˈruːt/', 'noun', 'A number that gives a given number when multiplied by itself.', 'Số mà khi nhân với chính nó thì được số đã cho.', 'The square root of 49 is 7.', 'Căn bậc hai của 49 là 7.', '', array['integer']::text[], 'published'),
  ('equation', 'math', 'm-alg', 8, 'equation', 'phương trình', '/ɪˈkweɪʒn/', 'noun', 'A mathematical statement with an equals sign, often with an unknown value to find.', 'Đẳng thức chứa ẩn số cần tìm.', 'Solve the equation 2x + 3 = 11.', 'Giải phương trình 2x + 3 = 11.', 'Động từ đi kèm là "solve" (giải): solve an equation.', array['variable-math','expression']::text[], 'published'),
  ('variable-math', 'math', 'm-alg', 7, 'variable', 'biến (ẩn)', '/ˈveəriəbl/', 'noun', 'A letter, such as x or y, that stands for an unknown number.', 'Chữ cái như x, y dùng để đại diện cho một số chưa biết.', 'In 3x + 1, x is the variable.', 'Trong 3x + 1, x là biến.', 'Tin học cũng dùng "variable" (biến trong lập trình).', array['equation','expression']::text[], 'published'),
  ('expression', 'math', 'm-alg', 7, 'expression', 'biểu thức', '/ɪkˈspreʃn/', 'noun', 'Numbers, letters and operation signs put together, with no equals sign.', 'Tập hợp số, chữ và dấu phép tính, không có dấu bằng.', 'Simplify the expression 2(a + 3) − a.', 'Rút gọn biểu thức 2(a + 3) − a.', 'Expression không có dấu "=", còn equation có.', array['equation','polynomial']::text[], 'published'),
  ('polynomial', 'math', 'm-alg', 7, 'polynomial', 'đa thức', '/ˌpɒliˈnəʊmiəl/', 'noun', 'An expression made of several terms added or subtracted, such as x² + 3x − 5.', 'Tổng của nhiều đơn thức, ví dụ x² + 3x − 5.', 'Find the degree of the polynomial 4x³ − x + 2.', 'Tìm bậc của đa thức 4x³ − x + 2.', '', array['expression']::text[], 'published'),
  ('triangle', 'math', 'm-geo', 6, 'triangle', 'tam giác', '/ˈtraɪæŋɡl/', 'noun', 'A flat shape with three straight sides and three angles.', 'Hình phẳng có ba cạnh thẳng và ba góc.', 'The angles in a triangle add up to 180 degrees.', 'Tổng ba góc trong một tam giác bằng 180 độ.', '', array['right-angle','hypotenuse','perimeter']::text[], 'published'),
  ('right-angle', 'math', 'm-geo', 6, 'right angle', 'góc vuông', '/ˌraɪt ˈæŋɡl/', 'noun', 'An angle of exactly 90 degrees.', 'Góc có số đo đúng 90 độ.', 'A square has four right angles.', 'Hình vuông có bốn góc vuông.', '"right" ở đây nghĩa là "vuông", không phải "bên phải" hay "đúng".', array['triangle','hypotenuse']::text[], 'published'),
  ('perimeter', 'math', 'm-geo', 6, 'perimeter', 'chu vi', '/pəˈrɪmɪtə(r)/', 'noun', 'The total length of the outside edge of a shape.', 'Tổng độ dài đường bao quanh một hình.', 'The perimeter of a square with sides of 5 cm is 20 cm.', 'Chu vi hình vuông cạnh 5 cm là 20 cm.', 'Đừng nhầm với "area" (diện tích). Chu vi đo bằng cm, diện tích đo bằng cm².', array['area']::text[], 'published'),
  ('area', 'math', 'm-geo', 6, 'area', 'diện tích', '/ˈeəriə/', 'noun', 'The size of a flat surface, measured in square units.', 'Độ lớn của một bề mặt phẳng, đo bằng đơn vị vuông.', 'The area of the rectangle is 24 square centimetres.', 'Diện tích hình chữ nhật là 24 cm².', 'Trong văn nói hằng ngày, "area" còn có nghĩa là "khu vực".', array['perimeter']::text[], 'published'),
  ('parallel-lines', 'math', 'm-geo', 7, 'parallel lines', 'hai đường thẳng song song', '/ˈpærəlel laɪnz/', 'noun', 'Lines on the same flat surface that never meet.', 'Các đường thẳng cùng nằm trên một mặt phẳng và không bao giờ cắt nhau.', 'Railway tracks are a good example of parallel lines.', 'Đường ray tàu hoả là ví dụ điển hình của hai đường thẳng song song.', '', array['right-angle']::text[], 'published'),
  ('hypotenuse', 'math', 'm-geo', 8, 'hypotenuse', 'cạnh huyền', '/haɪˈpɒtənjuːz/', 'noun', 'The longest side of a right triangle, opposite the right angle.', 'Cạnh dài nhất của tam giác vuông, đối diện với góc vuông.', 'Use Pythagoras'' theorem to find the hypotenuse.', 'Dùng định lí Pythagore để tìm cạnh huyền.', '', array['triangle','right-angle']::text[], 'published'),
  ('radius', 'math', 'm-geo', 9, 'radius', 'bán kính', '/ˈreɪdiəs/', 'noun', 'The distance from the centre of a circle to its edge.', 'Khoảng cách từ tâm đường tròn đến một điểm trên đường tròn.', 'A circle with a radius of 3 cm has a diameter of 6 cm.', 'Đường tròn bán kính 3 cm có đường kính 6 cm.', 'Số nhiều: radii /ˈreɪdiaɪ/. "diameter" = đường kính.', array['area']::text[], 'published'),
  ('mean', 'math', 'm-stat', 7, 'mean', 'số trung bình cộng', '/miːn/', 'noun', 'The average: the sum of all values divided by the number of values.', 'Tổng các giá trị chia cho số các giá trị.', 'The mean of 4, 6 and 8 is 6.', 'Số trung bình cộng của 4, 6 và 8 là 6.', 'Động từ "mean" còn có nghĩa là "có nghĩa là". Trong thống kê, "mean" là danh từ.', array['probability']::text[], 'published'),
  ('probability', 'math', 'm-stat', 7, 'probability', 'xác suất', '/ˌprɒbəˈbɪləti/', 'noun', 'How likely something is to happen, from 0 (impossible) to 1 (certain).', 'Khả năng xảy ra của một sự kiện, từ 0 (không thể) đến 1 (chắc chắn).', 'The probability of getting heads when you toss a coin is 1/2.', 'Xác suất tung đồng xu được mặt ngửa là 1/2.', '', array['mean','fraction']::text[], 'published'),
  ('force', 'science', 's-phy', 6, 'force', 'lực', '/fɔːs/', 'noun', 'A push or a pull that can change how an object moves or its shape.', 'Tác dụng đẩy hoặc kéo, có thể làm thay đổi chuyển động hoặc hình dạng của vật.', 'Force is measured in newtons (N).', 'Lực được đo bằng đơn vị newton (N).', '', array['friction','gravity','pressure']::text[], 'published'),
  ('friction', 'science', 's-phy', 6, 'friction', 'lực ma sát', '/ˈfrɪkʃn/', 'noun', 'A force that slows down objects when they rub against each other.', 'Lực cản xuất hiện khi hai bề mặt cọ xát vào nhau.', 'Friction between the tyres and the road helps the bike stop.', 'Ma sát giữa lốp xe và mặt đường giúp xe đạp dừng lại.', '', array['force']::text[], 'published'),
  ('gravity', 'science', 's-phy', 6, 'gravity', 'lực hấp dẫn, trọng lực', '/ˈɡrævəti/', 'noun', 'The force that pulls objects towards the Earth or towards each other.', 'Lực hút các vật về phía Trái Đất hoặc hút các vật về phía nhau.', 'An apple falls to the ground because of gravity.', 'Quả táo rơi xuống đất vì trọng lực.', '', array['weight','force','mass']::text[], 'published'),
  ('mass', 'science', 's-phy', 6, 'mass', 'khối lượng', '/mæs/', 'noun', 'The amount of matter in an object, measured in kilograms.', 'Lượng chất chứa trong vật, đo bằng kilôgam.', 'The mass of this bag of rice is 5 kg.', 'Khối lượng túi gạo này là 5 kg.', 'Lỗi thường gặp: "mass" (khối lượng, kg) khác "weight" (trọng lượng, N). Trên Mặt Trăng, khối lượng không đổi nhưng trọng lượng giảm.', array['weight','density']::text[], 'published'),
  ('weight', 'science', 's-phy', 6, 'weight', 'trọng lượng', '/weɪt/', 'noun', 'The force of gravity on an object, measured in newtons.', 'Độ lớn lực hút của Trái Đất lên vật, đo bằng newton.', 'An astronaut''s weight is smaller on the Moon.', 'Trọng lượng của phi hành gia nhỏ hơn khi ở trên Mặt Trăng.', 'Trong đời sống, "weight" thường dùng với nghĩa cân nặng (kg). Trong vật lí, weight là một lực, đơn vị là N.', array['mass','gravity']::text[], 'published'),
  ('speed', 'science', 's-phy', 7, 'speed', 'tốc độ', '/spiːd/', 'noun', 'How fast something moves: distance divided by time.', 'Độ nhanh hay chậm của chuyển động, bằng quãng đường chia cho thời gian.', 'The car travels at a speed of 60 km/h.', 'Ô tô chuyển động với tốc độ 60 km/h.', '', array['force','energy']::text[], 'published'),
  ('energy', 'science', 's-phy', 6, 'energy', 'năng lượng', '/ˈenədʒi/', 'noun', 'The ability to do work or cause change. It can change from one form to another.', 'Khả năng thực hiện công hoặc gây ra biến đổi; có thể chuyển hoá từ dạng này sang dạng khác.', 'Solar panels change light energy into electrical energy.', 'Tấm pin mặt trời chuyển hoá quang năng thành điện năng.', '', array['electric-current','photosynthesis']::text[], 'published'),
  ('pressure', 'science', 's-phy', 8, 'pressure', 'áp suất', '/ˈpreʃə(r)/', 'noun', 'The force acting on a unit of area.', 'Độ lớn của áp lực trên một đơn vị diện tích.', 'A sharp knife cuts well because it creates high pressure.', 'Dao sắc cắt tốt vì tạo ra áp suất lớn.', 'Ngoài đời, "pressure" còn có nghĩa là "áp lực" (ví dụ: exam pressure).', array['force','area']::text[], 'published'),
  ('density', 'science', 's-phy', 8, 'density', 'khối lượng riêng', '/ˈdensəti/', 'noun', 'How much mass is in a given volume: mass divided by volume.', 'Khối lượng của một đơn vị thể tích chất, bằng khối lượng chia cho thể tích.', 'Oil floats on water because its density is lower.', 'Dầu nổi trên nước vì khối lượng riêng của dầu nhỏ hơn.', '', array['mass']::text[], 'published'),
  ('electric-current', 'science', 's-phy', 8, 'electric current', 'dòng điện', '/ɪˌlektrɪk ˈkʌrənt/', 'noun', 'A flow of electric charge, measured in amperes (A).', 'Dòng các điện tích dịch chuyển có hướng, đo bằng ampe (A).', 'An ammeter measures the electric current in a circuit.', 'Ampe kế đo cường độ dòng điện trong mạch.', '"current" còn có nghĩa là "hiện tại" (current events) hoặc "dòng chảy" (ocean current).', array['energy']::text[], 'published'),
  ('reflection', 'science', 's-phy', 7, 'reflection', 'sự phản xạ', '/rɪˈflekʃn/', 'noun', 'When light or sound bounces back from a surface.', 'Hiện tượng ánh sáng hoặc âm thanh bị hắt trở lại khi gặp một bề mặt.', 'We can see ourselves in a mirror because of reflection.', 'Ta thấy mình trong gương là nhờ sự phản xạ ánh sáng.', '', array['lens']::text[], 'published'),
  ('lens', 'science', 's-phy', 9, 'lens', 'thấu kính', '/lenz/', 'noun', 'A curved piece of glass or plastic that bends light.', 'Khối thuỷ tinh hoặc nhựa có mặt cong, làm khúc xạ ánh sáng.', 'A magnifying glass uses a convex lens.', 'Kính lúp sử dụng thấu kính hội tụ.', 'convex lens = thấu kính hội tụ; concave lens = thấu kính phân kì.', array['reflection']::text[], 'published'),
  ('atom', 'science', 's-chem', 7, 'atom', 'nguyên tử', '/ˈætəm/', 'noun', 'The smallest particle of a chemical element.', 'Hạt vô cùng nhỏ cấu tạo nên chất, là đơn vị nhỏ nhất của nguyên tố hoá học.', 'A water molecule contains two hydrogen atoms and one oxygen atom.', 'Một phân tử nước gồm hai nguyên tử hydrogen và một nguyên tử oxygen.', '', array['molecule','element']::text[], 'published'),
  ('molecule', 'science', 's-chem', 7, 'molecule', 'phân tử', '/ˈmɒlɪkjuːl/', 'noun', 'A group of atoms joined together.', 'Hạt gồm các nguyên tử liên kết với nhau.', 'The formula of a carbon dioxide molecule is CO₂.', 'Công thức phân tử carbon dioxide là CO₂.', '', array['atom','compound']::text[], 'published'),
  ('element', 'science', 's-chem', 7, 'element', 'nguyên tố hoá học', '/ˈelɪmənt/', 'noun', 'A pure substance made of only one type of atom.', 'Tập hợp các nguyên tử cùng loại.', 'Oxygen, iron and gold are elements.', 'Oxygen, sắt và vàng là các nguyên tố hoá học.', 'Ngoài hoá học, "element" còn có nghĩa là "yếu tố, thành phần".', array['periodic-table','atom','compound']::text[], 'published'),
  ('compound', 'science', 's-chem', 7, 'compound', 'hợp chất', '/ˈkɒmpaʊnd/', 'noun', 'A substance made of two or more different elements chemically joined.', 'Chất được tạo nên từ hai hay nhiều nguyên tố hoá học khác nhau.', 'Water (H₂O) is a compound of hydrogen and oxygen.', 'Nước (H₂O) là hợp chất của hydrogen và oxygen.', 'Compound khác mixture: các chất trong hỗn hợp không liên kết hoá học với nhau.', array['element','mixture','molecule']::text[], 'published'),
  ('mixture', 'science', 's-chem', 6, 'mixture', 'hỗn hợp', '/ˈmɪkstʃə(r)/', 'noun', 'Two or more substances mixed together but not chemically joined.', 'Hai hay nhiều chất trộn lẫn với nhau nhưng không phản ứng hoá học.', 'Salt water is a mixture of salt and water.', 'Nước muối là hỗn hợp của muối và nước.', '', array['solution','compound']::text[], 'published'),
  ('solution', 'science', 's-chem', 6, 'solution', 'dung dịch', '/səˈluːʃn/', 'noun', 'A liquid in which a substance has been completely dissolved.', 'Hỗn hợp đồng nhất của chất tan và dung môi.', 'Sugar dissolves in water to form a solution.', 'Đường tan trong nước tạo thành dung dịch.', 'Lỗi thường gặp: trong Toán, "solution" là "lời giải, nghiệm". Trong Hoá, "solution" là "dung dịch".', array['mixture','acid']::text[], 'published'),
  ('chemical-reaction', 'science', 's-chem', 8, 'chemical reaction', 'phản ứng hoá học', '/ˌkemɪkl riˈækʃn/', 'noun', 'A process in which substances change into new substances.', 'Quá trình biến đổi từ chất này thành chất khác.', 'Burning paper is a chemical reaction.', 'Đốt giấy là một phản ứng hoá học.', '', array['compound','oxygen']::text[], 'published'),
  ('acid', 'science', 's-chem', 8, 'acid', 'acid', '/ˈæsɪd/', 'noun', 'A substance with a pH lower than 7 that turns blue litmus paper red.', 'Chất có pH nhỏ hơn 7, làm quỳ tím chuyển sang màu đỏ.', 'Lemon juice contains citric acid.', 'Nước chanh chứa citric acid.', 'Chương trình mới dùng tên gọi theo IUPAC: "acid", "base" thay cho "axit", "bazơ".', array['base','solution']::text[], 'published'),
  ('base', 'science', 's-chem', 8, 'base', 'base', '/beɪs/', 'noun', 'A substance with a pH higher than 7 that turns red litmus paper blue.', 'Chất có pH lớn hơn 7, làm quỳ tím chuyển sang màu xanh.', 'Soap and baking soda are bases.', 'Xà phòng và baking soda có tính base.', '"base" trong đời thường là "nền, đáy, căn cứ".', array['acid']::text[], 'published'),
  ('oxygen', 'science', 's-chem', 6, 'oxygen', 'oxygen', '/ˈɒksɪdʒən/', 'noun', 'A gas in the air that living things need to breathe and that is needed for burning.', 'Chất khí có trong không khí, cần cho sự hô hấp và sự cháy.', 'Oxygen makes up about 21% of the air.', 'Oxygen chiếm khoảng 21% thể tích không khí.', '', array['respiration','photosynthesis','element']::text[], 'published'),
  ('periodic-table', 'science', 's-chem', 7, 'periodic table', 'bảng tuần hoàn', '/ˌpɪəriɒdɪk ˈteɪbl/', 'noun', 'A table that arranges all chemical elements by their atomic number.', 'Bảng sắp xếp các nguyên tố hoá học theo chiều tăng dần của số hiệu nguyên tử.', 'Find sodium (Na) in the periodic table.', 'Tìm sodium (Na) trong bảng tuần hoàn.', '', array['element','metal']::text[], 'published'),
  ('metal', 'science', 's-chem', 9, 'metal', 'kim loại', '/ˈmetl/', 'noun', 'A shiny, hard material that conducts heat and electricity well.', 'Vật liệu có ánh kim, dẫn nhiệt và dẫn điện tốt.', 'Copper is a metal used in electric wires.', 'Đồng là kim loại được dùng làm dây điện.', '', array['periodic-table','element']::text[], 'published'),
  ('cell', 'science', 's-bio', 6, 'cell', 'tế bào', '/sel/', 'noun', 'The smallest unit of a living thing.', 'Đơn vị cấu trúc và chức năng nhỏ nhất của cơ thể sống.', 'We use a microscope to observe onion cells.', 'Chúng ta dùng kính hiển vi để quan sát tế bào vảy hành.', '"cell" còn có nghĩa là "ô" trong bảng tính và "pin" (solar cell).', array['organism','gene']::text[], 'published'),
  ('organism', 'science', 's-bio', 6, 'organism', 'sinh vật', '/ˈɔːɡənɪzəm/', 'noun', 'Any living thing, such as a plant, an animal or a bacterium.', 'Cơ thể sống, ví dụ thực vật, động vật, vi khuẩn.', 'Single-celled organisms have only one cell.', 'Sinh vật đơn bào chỉ có một tế bào.', '', array['cell','ecosystem','bacteria']::text[], 'published'),
  ('photosynthesis', 'science', 's-bio', 7, 'photosynthesis', 'quang hợp', '/ˌfəʊtəʊˈsɪnθəsɪs/', 'noun', 'The process by which green plants use sunlight, water and carbon dioxide to make food and release oxygen.', 'Quá trình cây xanh dùng ánh sáng, nước và khí carbon dioxide để tạo chất hữu cơ và thải ra oxygen.', 'Leaves are the main place where photosynthesis happens.', 'Lá là nơi diễn ra quá trình quang hợp chủ yếu.', '', array['respiration','oxygen','energy']::text[], 'published'),
  ('respiration', 'science', 's-bio', 7, 'respiration', 'hô hấp', '/ˌrespəˈreɪʃn/', 'noun', 'The process by which living things break down food to release energy.', 'Quá trình sinh vật phân giải chất hữu cơ để giải phóng năng lượng.', 'Cellular respiration uses oxygen and produces carbon dioxide.', 'Hô hấp tế bào sử dụng oxygen và tạo ra carbon dioxide.', '"respiration" (hô hấp tế bào) khác "breathing" (sự thở).', array['photosynthesis','oxygen']::text[], 'published'),
  ('ecosystem', 'science', 's-bio', 8, 'ecosystem', 'hệ sinh thái', '/ˈiːkəʊsɪstəm/', 'noun', 'All the living things in an area and their environment, working together.', 'Quần xã sinh vật cùng với môi trường sống của chúng, tác động qua lại với nhau.', 'A mangrove forest is an important ecosystem.', 'Rừng ngập mặn là một hệ sinh thái quan trọng.', '', array['food-chain','organism']::text[], 'published'),
  ('food-chain', 'science', 's-bio', 8, 'food chain', 'chuỗi thức ăn', '/ˈfuːd tʃeɪn/', 'noun', 'A series of living things in which each one is eaten by the next.', 'Dãy các loài sinh vật, trong đó loài này là thức ăn của loài tiếp theo.', 'Grass → grasshopper → frog → snake is a food chain.', 'Cỏ → châu chấu → ếch → rắn là một chuỗi thức ăn.', 'Nhiều chuỗi thức ăn liên kết với nhau tạo thành "food web" (lưới thức ăn).', array['ecosystem']::text[], 'published'),
  ('gene', 'science', 's-bio', 9, 'gene', 'gene', '/dʒiːn/', 'noun', 'A part of DNA that controls a characteristic passed from parents to children.', 'Đoạn DNA mang thông tin quy định một tính trạng, được di truyền từ bố mẹ sang con.', 'Eye colour is controlled by genes.', 'Màu mắt do gene quy định.', '', array['cell']::text[], 'published'),
  ('bacteria', 'science', 's-bio', 6, 'bacteria', 'vi khuẩn', '/bækˈtɪəriə/', 'noun (plural)', 'Very small single-celled organisms. Some are useful, some cause disease.', 'Sinh vật đơn bào rất nhỏ; một số có ích, một số gây bệnh.', 'Yoghurt is made with the help of bacteria.', 'Sữa chua được làm nhờ vi khuẩn.', '"bacteria" là số nhiều; số ít là "bacterium".', array['organism','vaccine','virus']::text[], 'published'),
  ('nutrient', 'science', 's-bio', 7, 'nutrient', 'chất dinh dưỡng', '/ˈnjuːtriənt/', 'noun', 'A substance in food that living things need to grow and stay healthy.', 'Chất có trong thức ăn mà sinh vật cần để sinh trưởng và phát triển.', 'Proteins, fats and vitamins are nutrients.', 'Protein, chất béo và vitamin là các chất dinh dưỡng.', '', array['organism']::text[], 'published'),
  ('skeleton', 'science', 's-bio', 8, 'skeleton', 'bộ xương', '/ˈskelɪtn/', 'noun', 'The frame of bones that supports and protects the body.', 'Hệ thống các xương nâng đỡ và bảo vệ cơ thể.', 'The adult human skeleton has 206 bones.', 'Bộ xương người trưởng thành có 206 chiếc xương.', '', '{}'::text[], 'published'),
  ('vaccine', 'science', 's-bio', 8, 'vaccine', 'vaccine', '/ˈvæksiːn/', 'noun', 'A substance that helps the body build protection against a disease.', 'Chế phẩm giúp cơ thể tạo miễn dịch chống lại một bệnh.', 'Vaccines protect children from measles.', 'Vaccine bảo vệ trẻ em khỏi bệnh sởi.', '', array['bacteria']::text[], 'published'),
  ('dynasty', 'histgeo', 'h-his', 7, 'dynasty', 'triều đại', '/ˈdɪnəsti/', 'noun', 'A series of rulers from the same family.', 'Dòng các vua thuộc cùng một dòng họ nối tiếp nhau cai trị.', 'The Ly dynasty moved the capital to Thang Long in 1010.', 'Nhà Lý dời đô ra Thăng Long năm 1010.', '', array['empire','independence']::text[], 'published'),
  ('ancient', 'histgeo', 'h-his', 6, 'ancient', 'cổ đại', '/ˈeɪnʃənt/', 'adjective', 'Belonging to a time very long ago in history.', 'Thuộc về thời kì rất xa xưa trong lịch sử.', 'The pyramids were built in ancient Egypt.', 'Kim tự tháp được xây dựng thời Ai Cập cổ đại.', '', array['civilization','archaeology']::text[], 'published'),
  ('civilization', 'histgeo', 'h-his', 6, 'civilization', 'nền văn minh', '/ˌsɪvəlaɪˈzeɪʃn/', 'noun', 'A developed society with its own culture, government and way of life.', 'Xã hội phát triển, có văn hoá, nhà nước và lối sống riêng.', 'The Dong Son civilization is famous for its bronze drums.', 'Văn minh Đông Sơn nổi tiếng với trống đồng.', 'Anh-Anh có thể viết "civilisation".', array['ancient','empire']::text[], 'published'),
  ('archaeology', 'histgeo', 'h-his', 6, 'archaeology', 'khảo cổ học', '/ˌɑːkiˈɒlədʒi/', 'noun', 'The study of the past by digging up and examining old objects.', 'Ngành khoa học nghiên cứu quá khứ qua di tích và hiện vật.', 'Archaeology helps us learn how ancient people lived.', 'Khảo cổ học giúp ta biết người xưa đã sống như thế nào.', 'Người làm khảo cổ: "archaeologist".', array['primary-source','ancient']::text[], 'published'),
  ('independence', 'histgeo', 'h-his', 6, 'independence', 'độc lập', '/ˌɪndɪˈpendəns/', 'noun', 'Freedom of a country from control by another country.', 'Trạng thái một quốc gia không bị nước khác cai trị.', 'Vietnam''s Declaration of Independence was read on 2 September 1945.', 'Tuyên ngôn Độc lập của Việt Nam được đọc ngày 2/9/1945.', '', array['revolution','colony']::text[], 'published'),
  ('revolution', 'histgeo', 'h-his', 8, 'revolution', 'cách mạng', '/ˌrevəˈluːʃn/', 'noun', 'A great change in a country''s government or in the way people live and work.', 'Cuộc biến đổi lớn về chính quyền hoặc về cách con người sống và lao động.', 'The Industrial Revolution began in Britain.', 'Cách mạng công nghiệp bắt đầu ở Anh.', '', array['independence']::text[], 'published'),
  ('colony', 'histgeo', 'h-his', 8, 'colony', 'thuộc địa', '/ˈkɒləni/', 'noun', 'A country or area controlled by another, more powerful country.', 'Vùng đất hoặc quốc gia bị một nước khác cai trị.', 'Many Asian countries were colonies in the 19th century.', 'Nhiều nước châu Á là thuộc địa vào thế kỉ XIX.', 'Trong Sinh học, "colony" còn có nghĩa là "tập đoàn" (ví dụ: a colony of ants).', array['empire','independence']::text[], 'published'),
  ('empire', 'histgeo', 'h-his', 6, 'empire', 'đế quốc, đế chế', '/ˈempaɪə(r)/', 'noun', 'A group of countries or lands ruled by one ruler or one powerful country.', 'Nhiều vùng đất hoặc quốc gia chịu sự cai trị của một hoàng đế hay một nước mạnh.', 'The Roman Empire was very large.', 'Đế quốc La Mã có lãnh thổ rất rộng lớn.', '', array['dynasty','colony']::text[], 'published'),
  ('resistance', 'histgeo', 'h-his', 9, 'resistance', 'kháng chiến', '/rɪˈzɪstəns/', 'noun', 'Fighting against an enemy or against someone who controls you.', 'Cuộc chiến đấu chống lại kẻ thù xâm lược.', 'The resistance war against the French ended in 1954.', 'Cuộc kháng chiến chống Pháp kết thúc năm 1954.', 'Trong Vật lí, "resistance" là "điện trở".', array['independence']::text[], 'published'),
  ('primary-source', 'histgeo', 'h-his', 6, 'primary source', 'tư liệu gốc', '/ˌpraɪməri ˈsɔːs/', 'noun', 'An original document or object from the time being studied.', 'Tư liệu được tạo ra vào chính thời kì được nghiên cứu.', 'Old letters and photographs are primary sources.', 'Thư từ và ảnh cũ là tư liệu gốc.', '', array['archaeology']::text[], 'published'),
  ('latitude', 'histgeo', 'h-geo', 6, 'latitude', 'vĩ độ', '/ˈlætɪtjuːd/', 'noun', 'The distance of a place north or south of the equator, measured in degrees.', 'Khoảng cách từ một địa điểm đến xích đạo theo hướng bắc hoặc nam, tính bằng độ.', 'Hanoi is at a latitude of about 21° North.', 'Hà Nội nằm ở vĩ độ khoảng 21° Bắc.', 'Mẹo nhớ: latitude là các đường nằm ngang, giống bậc thang (ladder).', array['longitude','equator']::text[], 'published'),
  ('longitude', 'histgeo', 'h-geo', 6, 'longitude', 'kinh độ', '/ˈlɒŋɡɪtjuːd/', 'noun', 'The distance of a place east or west of the Prime Meridian, measured in degrees.', 'Khoảng cách từ một địa điểm đến kinh tuyến gốc theo hướng đông hoặc tây, tính bằng độ.', 'Vietnam lies between longitudes 102° and 110° East.', 'Phần đất liền Việt Nam nằm trong khoảng kinh độ 102° Đ đến 110° Đ.', '', array['latitude']::text[], 'published'),
  ('equator', 'histgeo', 'h-geo', 6, 'equator', 'xích đạo', '/ɪˈkweɪtə(r)/', 'noun', 'An imaginary line around the middle of the Earth, at 0° latitude.', 'Đường tưởng tượng chia Trái Đất thành hai bán cầu, ở vĩ độ 0°.', 'Countries near the equator are hot all year.', 'Các nước gần xích đạo nóng quanh năm.', '', array['latitude','climate']::text[], 'published'),
  ('climate', 'histgeo', 'h-geo', 6, 'climate', 'khí hậu', '/ˈklaɪmət/', 'noun', 'The usual weather in a place over a long period of time.', 'Tình trạng thời tiết đặc trưng của một nơi trong thời gian dài.', 'Vietnam has a tropical monsoon climate.', 'Việt Nam có khí hậu nhiệt đới gió mùa.', '"climate" (khí hậu, lâu dài) khác "weather" (thời tiết, ngắn hạn).', array['equator','erosion']::text[], 'published'),
  ('population', 'histgeo', 'h-geo', 7, 'population', 'dân số', '/ˌpɒpjuˈleɪʃn/', 'noun', 'The number of people living in an area.', 'Số người sống trong một khu vực.', 'The population of Vietnam is over 100 million.', 'Dân số Việt Nam hơn 100 triệu người.', 'Trong Sinh học, "population" là "quần thể".', array['urbanization']::text[], 'published'),
  ('delta', 'histgeo', 'h-geo', 8, 'delta', 'đồng bằng châu thổ', '/ˈdeltə/', 'noun', 'Flat land where a river divides into smaller rivers before it flows into the sea.', 'Vùng đất bằng phẳng ở cửa sông, nơi sông chia nhánh trước khi đổ ra biển.', 'The Mekong Delta is called the rice bowl of Vietnam.', 'Đồng bằng sông Cửu Long được gọi là vựa lúa của Việt Nam.', '', array['plateau','erosion']::text[], 'published'),
  ('plateau', 'histgeo', 'h-geo', 6, 'plateau', 'cao nguyên', '/ˈplætəʊ/', 'noun', 'A large area of high, fairly flat land.', 'Vùng đất cao, tương đối bằng phẳng, rộng lớn.', 'The Central Highlands has many basalt plateaus.', 'Tây Nguyên có nhiều cao nguyên đất đỏ badan.', 'Số nhiều: plateaus hoặc plateaux.', array['delta']::text[], 'published'),
  ('erosion', 'histgeo', 'h-geo', 8, 'erosion', 'sự xói mòn', '/ɪˈrəʊʒn/', 'noun', 'The slow wearing away of soil or rock by water, wind or ice.', 'Quá trình đất đá bị bào mòn dần bởi nước, gió hoặc băng.', 'Planting trees on hills helps prevent soil erosion.', 'Trồng cây trên đồi giúp chống xói mòn đất.', '', array['climate','natural-resources']::text[], 'published'),
  ('natural-resources', 'histgeo', 'h-geo', 8, 'natural resources', 'tài nguyên thiên nhiên', '/ˌnætʃrəl rɪˈsɔːsɪz/', 'noun', 'Materials from nature that people use, such as water, forests and minerals.', 'Các nguồn vật chất trong tự nhiên con người sử dụng, như nước, rừng, khoáng sản.', 'We must use natural resources wisely.', 'Chúng ta cần sử dụng tài nguyên thiên nhiên hợp lí.', '', array['erosion']::text[], 'published'),
  ('urbanization', 'histgeo', 'h-geo', 9, 'urbanization', 'đô thị hoá', '/ˌɜːbənaɪˈzeɪʃn/', 'noun', 'The process of more people moving to and living in cities.', 'Quá trình dân cư tập trung ngày càng đông vào các thành phố.', 'Fast urbanization causes traffic jams in big cities.', 'Đô thị hoá nhanh gây ùn tắc giao thông ở các thành phố lớn.', 'Anh-Anh có thể viết "urbanisation".', array['population']::text[], 'published'),
  ('hardware', 'it', 'i-comp', 6, 'hardware', 'phần cứng', '/ˈhɑːdweə(r)/', 'noun', 'The physical parts of a computer that you can touch.', 'Các bộ phận vật lí của máy tính mà ta có thể chạm vào.', 'The keyboard, mouse and monitor are hardware.', 'Bàn phím, chuột và màn hình là phần cứng.', '"hardware" là danh từ không đếm được: không viết "hardwares".', array['software','input-device']::text[], 'published'),
  ('software', 'it', 'i-comp', 6, 'software', 'phần mềm', '/ˈsɒftweə(r)/', 'noun', 'Programs and instructions that tell a computer what to do.', 'Các chương trình và chỉ dẫn điều khiển máy tính hoạt động.', 'We use word processing software to write reports.', 'Chúng ta dùng phần mềm soạn thảo văn bản để viết báo cáo.', 'Danh từ không đếm được: dùng "a piece of software" hoặc "software programs".', array['hardware','operating-system']::text[], 'published'),
  ('input-device', 'it', 'i-comp', 6, 'input device', 'thiết bị vào', '/ˈɪnpʊt dɪˌvaɪs/', 'noun', 'A device used to put information into a computer.', 'Thiết bị dùng để đưa thông tin vào máy tính.', 'A microphone is an input device.', 'Micro là một thiết bị vào.', 'Ngược lại: "output device" (thiết bị ra), ví dụ loa, máy in.', array['hardware']::text[], 'published'),
  ('operating-system', 'it', 'i-comp', 7, 'operating system', 'hệ điều hành', '/ˈɒpəreɪtɪŋ ˌsɪstəm/', 'noun', 'The main software that controls a computer and lets other programs run.', 'Phần mềm quản lí máy tính và cho phép các chương trình khác hoạt động.', 'Windows and Android are operating systems.', 'Windows và Android là các hệ điều hành.', 'Viết tắt: OS.', array['software','file']::text[], 'published'),
  ('network', 'it', 'i-comp', 6, 'network', 'mạng máy tính', '/ˈnetwɜːk/', 'noun', 'A group of computers connected so they can share information.', 'Nhóm máy tính được kết nối để chia sẻ thông tin.', 'The Internet is the largest computer network in the world.', 'Internet là mạng máy tính lớn nhất thế giới.', '', array['browser','data']::text[], 'published'),
  ('browser', 'it', 'i-comp', 6, 'web browser', 'trình duyệt web', '/ˈweb ˌbraʊzə(r)/', 'noun', 'A program used to view websites.', 'Phần mềm dùng để truy cập và xem các trang web.', 'Open a web browser and type the website address.', 'Mở trình duyệt web và gõ địa chỉ trang web.', '', array['search-engine','network']::text[], 'published'),
  ('data', 'it', 'i-comp', 6, 'data', 'dữ liệu', '/ˈdeɪtə/', 'noun', 'Facts, numbers or information stored and processed by a computer.', 'Sự kiện, con số hoặc thông tin được máy tính lưu trữ và xử lí.', 'The computer stores data on a hard disk.', 'Máy tính lưu dữ liệu trên ổ đĩa cứng.', 'Phân biệt: data (dữ liệu thô) và information (thông tin đã được xử lí, có ý nghĩa).', array['file','spreadsheet']::text[], 'published'),
  ('file', 'it', 'i-comp', 6, 'file', 'tệp (tin)', '/faɪl/', 'noun', 'A collection of data saved with a name on a computer.', 'Tập hợp dữ liệu được lưu trên máy tính với một tên riêng.', 'Save the file before you close the program.', 'Lưu tệp trước khi đóng chương trình.', '', array['folder','data']::text[], 'published'),
  ('folder', 'it', 'i-comp', 6, 'folder', 'thư mục', '/ˈfəʊldə(r)/', 'noun', 'A place on a computer where files are kept together.', 'Nơi chứa và sắp xếp các tệp trên máy tính.', 'Create a new folder called "Science project".', 'Tạo một thư mục mới tên là "Science project".', '', array['file']::text[], 'published'),
  ('spreadsheet', 'it', 'i-comp', 7, 'spreadsheet', 'bảng tính', '/ˈspredʃiːt/', 'noun', 'A program or document that organizes data in rows and columns.', 'Phần mềm hoặc tài liệu sắp xếp dữ liệu theo hàng và cột.', 'Use a spreadsheet to calculate the class average.', 'Dùng bảng tính để tính điểm trung bình của lớp.', 'Ô trong bảng tính gọi là "cell".', array['data','mean']::text[], 'published'),
  ('search-engine', 'it', 'i-comp', 6, 'search engine', 'máy tìm kiếm', '/ˈsɜːtʃ ˌendʒɪn/', 'noun', 'A website that helps you find information on the Internet using keywords.', 'Trang web giúp tìm thông tin trên Internet bằng từ khoá.', 'Type a keyword into the search engine.', 'Gõ từ khoá vào máy tìm kiếm.', '', array['browser']::text[], 'published'),
  ('algorithm', 'it', 'i-prog', 6, 'algorithm', 'thuật toán', '/ˈælɡərɪðəm/', 'noun', 'A set of step-by-step instructions to solve a problem.', 'Dãy các chỉ dẫn rõ ràng, theo từng bước để giải quyết một bài toán.', 'Write an algorithm to find the largest number in a list.', 'Viết thuật toán tìm số lớn nhất trong một dãy số.', '', array['loop','condition','debug']::text[], 'published'),
  ('loop', 'it', 'i-prog', 8, 'loop', 'vòng lặp', '/luːp/', 'noun', 'A part of a program that repeats instructions many times.', 'Cấu trúc lặp lại một nhóm lệnh nhiều lần.', 'Use a loop to print the numbers from 1 to 10.', 'Dùng vòng lặp để in các số từ 1 đến 10.', '', array['algorithm','condition','variable-it']::text[], 'published'),
  ('condition', 'it', 'i-prog', 8, 'condition', 'điều kiện (rẽ nhánh)', '/kənˈdɪʃn/', 'noun', 'A test in a program that is true or false and decides which instructions run next.', 'Biểu thức đúng hoặc sai trong chương trình, quyết định lệnh nào được thực hiện tiếp theo.', 'If the condition score >= 5 is true, print "Pass".', 'Nếu điều kiện score >= 5 đúng thì in ra "Pass".', 'Cấu trúc rẽ nhánh: "if … then … else".', array['loop','algorithm']::text[], 'published'),
  ('variable-it', 'it', 'i-prog', 8, 'variable', 'biến (lập trình)', '/ˈveəriəbl/', 'noun', 'A named place in memory that stores a value which can change.', 'Vùng nhớ được đặt tên để lưu một giá trị có thể thay đổi.', 'Create a variable called score and set it to 0.', 'Tạo một biến tên score và gán giá trị 0.', 'Trong Toán, "variable" là "biến, ẩn số".', array['loop','variable-math']::text[], 'published'),
  ('debug', 'it', 'i-prog', 8, 'debug', 'gỡ lỗi', '/ˌdiːˈbʌɡ/', 'verb', 'To find and fix mistakes in a computer program.', 'Tìm và sửa lỗi trong chương trình máy tính.', 'The program does not work, so we need to debug it.', 'Chương trình không chạy nên chúng ta cần gỡ lỗi.', 'Lỗi trong chương trình gọi là "bug".', array['algorithm']::text[], 'published'),
  ('password', 'it', 'i-safe', 6, 'password', 'mật khẩu', '/ˈpɑːswɜːd/', 'noun', 'A secret word or set of characters used to access an account.', 'Chuỗi kí tự bí mật dùng để đăng nhập tài khoản.', 'A strong password has letters, numbers and symbols.', 'Mật khẩu mạnh có chữ cái, chữ số và kí hiệu.', '', array['virus','cyberbullying']::text[], 'published'),
  ('virus', 'it', 'i-safe', 6, 'computer virus', 'virus máy tính', '/kəmˈpjuːtə ˌvaɪrəs/', 'noun', 'A harmful program that copies itself and damages computers or data.', 'Chương trình độc hại tự sao chép, gây hại cho máy tính hoặc dữ liệu.', 'Do not open strange email attachments; they may contain a virus.', 'Đừng mở tệp đính kèm lạ trong email vì có thể chứa virus.', 'Trong Sinh học, "virus" là "vi rút" gây bệnh.', array['password','bacteria']::text[], 'published'),
  ('cyberbullying', 'it', 'i-safe', 7, 'cyberbullying', 'bắt nạt qua mạng', '/ˈsaɪbəbʊliɪŋ/', 'noun', 'Using the Internet or phones to hurt, threaten or embarrass someone.', 'Dùng Internet hoặc điện thoại để làm tổn thương, đe doạ hoặc làm xấu hổ người khác.', 'If you see cyberbullying, tell a teacher or a parent.', 'Nếu thấy bắt nạt qua mạng, hãy báo cho thầy cô hoặc bố mẹ.', '', array['password','copyright']::text[], 'published'),
  ('copyright', 'it', 'i-safe', 7, 'copyright', 'bản quyền', '/ˈkɒpiraɪt/', 'noun', 'The legal right to control the copying and use of a creative work.', 'Quyền hợp pháp kiểm soát việc sao chép và sử dụng một tác phẩm.', 'Check the copyright before using a picture from the Internet.', 'Kiểm tra bản quyền trước khi dùng hình ảnh trên Internet.', 'Không phải "copy right" (sao chép đúng). Đây là "quyền" (right) đối với việc sao chép.', array['cyberbullying']::text[], 'published')
